// candidate reaches this read-only notice only after the real Training
// checkpoint. Dropping either losing read does not submit more work.
let progress = tokio::select! {
    decision = OriginalQ24SuccessorHandoffV1::decision_snapshot(&handoff) =>
        OriginalLearningProgress::Decision(decision.map_err(phase_owner_error)?),
    training = OriginalSameActorLearningWork::original_training_snapshot(work.as_ref()) =>
        OriginalLearningProgress::Training(training.map_err(phase_owner_error)?),
};
let snapshot = match progress {
    OriginalLearningProgress::Decision(snapshot) => snapshot,
    OriginalLearningProgress::Training(training) => {
        self.require_original_execution()?;
        OriginalCellQ24LearningStageOwnersV1::require_original_same_actor_work(
            owners.as_ref(), &work,
        ).map_err(phase_owner_error)?;
        let material = OriginalCellQ24LearningStageOwnersV1::read_original_training_material(
            owners.as_ref(), &training,
        ).await.map_err(phase_owner_error)?;
        self.require_original_execution()?;
        let readback = OriginalCellQ24LearningStageOwnersV1::original_training_readback(
            owners.as_ref(), training.clone(),
        ).await.map_err(phase_owner_error)?;
        self.require_original_execution()?;
        host.notify_original(
            &self.context,
            OriginalSameActorPhaseEventV1::OriginalTraining {
                snapshot: Box::new(training.clone()),
                material: Box::new(material),
                readback: Box::new(readback),
            },
        )?;
        let OriginalSameActorPhaseCommandV1::Evaluation(inputs) =
            host.receive_original(&self.context).await?
        else {
            return Err(phase_refused(
                "original Training requires B's independent Evaluation inputs",
            ));
        };
        self.require_original_execution()?;
        // This phase-only owner method rechecks the exact notified cut
        // under the original aggregate lane, calls the real installer,
        // and signals Learning only after successful installation and
        // release of that lane. An error never becomes Retain/NoUpdate.
        OriginalCellQ24LearningStageOwnersV1::install_original_same_actor_evaluation(
            owners.as_ref(), &training, *inputs,
        ).await.map_err(phase_owner_error)?;
        self.require_original_execution()?;
        OriginalQ24SuccessorHandoffV1::decision_snapshot(&handoff)
            .await.map_err(phase_owner_error)?
    }
};

